15	  const url = `${SITE_CONFIG.url}${path}`;
16	
17	  return {
18	    title,
19	    description,
20	    alternates: {
21	      canonical: url,
22	    },
23	    openGraph: {
24	      title,
25	      description,
26	      url,
27	      siteName: SITE_CONFIG.name,
28	      type: "website",
29	      ...(ogImage && {
30	        images: [{ url: ogImage, width: 1200, height: 630 }],
31	      }),
